<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import type {CalculationHistory,CalculationMethod,FormulaDraft,MethodField,PeakRecord} from '../peakRecordTypes';
import {calculationCatalog,evaluateCalculation,validateCalculation} from '../peakResultImportApi';
import {clonePeak} from '../peakResultImportState';
import {FIELD_LABELS} from '../peakRecordAdapters';
const props=defineProps<{records:PeakRecord[];modelValue:FormulaDraft;history:CalculationHistory[]}>();
const emit=defineEmits<{'update:modelValue':[draft:FormulaDraft];change:[];calculated:[history:CalculationHistory];activity:[value:boolean]}>();
const draft=ref(clonePeak(props.modelValue)),methods=ref<CalculationMethod[]>([]),busy=ref(false),loading=ref(false),error=ref(''),validation=ref('');
const selected=ref<string[]>(Array.isArray(props.modelValue.config.record_ids)?[...props.modelValue.config.record_ids]:[]),scope=ref<'all'|'selected'>(Array.isArray(props.modelValue.config.record_ids)?'selected':'all');
const method=computed(()=>methods.value.find(m=>m.id===draft.value.method));
const records=computed(()=>scope.value==='all'?props.records:props.records.filter(r=>selected.value.includes(r.id)));
const csvInput=ref<Record<string,string>>({});
watch(()=>props.modelValue,v=>{draft.value=clonePeak(v);selected.value=Array.isArray(v.config.record_ids)?[...v.config.record_ids]:[];scope.value=Array.isArray(v.config.record_ids)?'selected':'all';});
watch(()=>props.records,()=>{if(scope.value==='selected'){const ids=new Set(props.records.map(r=>r.id));const remaining=selected.value.filter(id=>ids.has(id));if(remaining.length!==selected.value.length){selected.value=remaining;selectionChanged();}}});
function edited(){validation.value='';emit('update:modelValue',clonePeak(draft.value));emit('change');}
function selectionChanged(){if(scope.value==='selected')draft.value.config.record_ids=[...selected.value];else delete draft.value.config.record_ids;edited();}
function selectMethod(){draft.value.config=clonePeak(method.value?.default_config??{});selectionChanged();}
async function load(){loading.value=true;try{methods.value=(await calculationCatalog()).methods;}catch(e){error.value=`计算方法加载失败：${(e as Error).message}`;}finally{loading.value=false;}}
onMounted(load);
function addVariable(){const v=draft.value.config.variables??={};let n=1;while(`v${n}` in v)n++;v[`v${n}`]={value:1,unit:'1'};edited();}
function renameVariable(old:string,name:string){name=name.trim();if(!name||name===old)return;if(!/^[A-Za-z][A-Za-z0-9_]*$/.test(name)||name in draft.value.config.variables){error.value='变量名需以字母开头，且不能重复。';return;}draft.value.config.variables[name]=draft.value.config.variables[old];delete draft.value.config.variables[old];edited();}
function bindingMode(name:string,mode:string){draft.value.config.variables[name]=mode==='field'?{field:'area'}:mode==='metadata'?{metadata:'temperature',unit:'K'}:{value:1,unit:'1'};edited();}
function addOutput(){(draft.value.config.outputs??=[]).push({name:`result${draft.value.config.outputs.length+1}`,expression:'',unit:'1'});edited();}
function optionValue(o:string|{value:string;label:string}){return typeof o==='string'?o:o.value;}
function optionLabel(o:string|{value:string;label:string}){return typeof o==='string'?o:o.label;}
function isHkl(key:string){return key==='hkl'||key==='reference_hkl';}
function correctionModeChanged(){const c=draft.value.config.correction;if(['corrected','apparent'].includes(c.mode)){for(const key of ['instrument_width','instrument_table','position_unit','width_unit'])delete c[key];}else if(!c.instrument_width&&!c.instrument_table){c.instrument_width={value:null,unit:'deg'};}edited();}
function correctionInput(mode:string){const c=draft.value.config.correction;if(mode==='table'){delete c.instrument_width;c.instrument_table=[];c.position_unit='deg';c.width_unit='deg';}else{delete c.instrument_table;c.instrument_width={value:.1,unit:'deg'};}edited();}
function addInstrumentRow(){(draft.value.config.correction.instrument_table??=[]).push({position:null,width:null});edited();}
function instrumentCsv(){try{const lines=(csvInput.value.correction??'').trim().split(/\r?\n/).filter(Boolean).map(l=>l.trim().split(/[\t,;]+/));if(lines[0]?.some(x=>!Number.isFinite(Number(x))))lines.shift();if(!lines.length||lines.some(r=>r.length!==2||r.some(x=>!x.trim()||!Number.isFinite(Number(x)))))throw new Error('仪器表每行需两个有限数值：2θ、宽度');draft.value.config.correction.instrument_table=lines.map(r=>({position:Number(r[0]),width:Number(r[1])}));delete draft.value.config.correction.instrument_width;edited();}catch(e){error.value=(e as Error).message;}}
function optionalQuantity(key:string,enabled:boolean){draft.value.config[key]=enabled?{value:key==='measured_d'?.2004:.15406,unit:'nm'}:null;edited();}
function toggleHkl(key:string,enabled:boolean){draft.value.config[key]=enabled?[1,1,1]:null;edited();}
function setRecordHkl(id:string,enabled:boolean){draft.value.config.hkl_by_record??={};if(enabled)draft.value.config.hkl_by_record[id]=[1,1,1];else delete draft.value.config.hkl_by_record[id];edited();}
function toggleCoefficients(enabled:boolean){draft.value.config.coefficients=enabled?{slope:1,intercept:0,min_concentration:0,max_concentration:1,source:''}:null;edited();}
function isTable(f:MethodField){return ['instrument_table','standards','calibration_points','points'].includes(f.key)||Array.isArray(draft.value.config[f.key])&&!isHkl(f.key);}
function tableColumns(f:MethodField):string[]{const rows=draft.value.config[f.key];const first=Array.isArray(rows)?rows.find(r=>r&&typeof r==='object'&&!Array.isArray(r)):null;if(first)return Object.keys(first);return f.key.includes('instrument')?['two_theta','width']:f.key.includes('standard')||f.key.includes('calibration')?['concentration','signal']:['x','y'];}
function addTableRow(f:MethodField){const rows=draft.value.config[f.key]??=[];rows.push(Object.fromEntries(tableColumns(f).map(k=>[k,null])));edited();}
function parseCsv(f:MethodField){try{const lines=(csvInput.value[f.key]??'').trim().split(/\r?\n/).filter(Boolean);const keys=tableColumns(f);if(!lines.length)throw new Error('请粘贴数据');const parts=lines.map(l=>l.trim().split(/[\t,;]+/).map(x=>x.trim()));if(parts[0].every(v=>!Number.isFinite(Number(v))))parts.shift();draft.value.config[f.key]=parts.map((r,i)=>{if(r.length!==keys.length||r.some(v=>!v||!Number.isFinite(Number(v))))throw new Error(`第 ${i+1} 行需 ${keys.length} 个有限数值`);return Object.fromEntries(keys.map((k,j)=>[k,Number(r[j])]));});edited();error.value='';}catch(e){error.value=(e as Error).message;}}
function objectEntries(f:MethodField):[string,any][]{const v=draft.value.config[f.key];return v&&typeof v==='object'&&!Array.isArray(v)?Object.entries(v):[];}
function addObjectField(f:MethodField,event:Event){const form=event.target as HTMLFormElement,key=(form.elements.namedItem('key')as HTMLInputElement).value.trim();if(!/^[A-Za-z][A-Za-z0-9_]*$/.test(key)||['constructor','prototype','__proto__'].includes(key)){error.value='请输入有效字段名';return;}(draft.value.config[f.key]??={})[key]='';form.reset();edited();}
async function run(checkOnly=false){
 if(busy.value||!records.value.length)return;busy.value=true;emit('activity',true);error.value='';validation.value='';
 const request={records:clonePeak(records.value),method:draft.value.method,config:clonePeak(draft.value.config)};
 try{const checked=await validateCalculation(request);if(!checked.valid){const text=checked.issues.map(i=>`${i.path?`${i.path}：`:''}${i.message} [${i.code}]`).join('；');if(checkOnly||checked.issues.some(i=>!i.record_ids?.length)){error.value=text;return;}validation.value=`部分记录不适用，将逐项保留失败原因并继续其他记录：${text}`;}else validation.value='表达式与配置检查通过；逐条数据的适用性在计算时检查。';if(checkOnly)return;
  const response=await evaluateCalculation(request);const stale=JSON.stringify(request)!==JSON.stringify({records:records.value,method:draft.value.method,config:draft.value.config});emit('calculated',{id:crypto.randomUUID(),created_at:new Date().toISOString(),request,response,stale,...(stale?{stale_reason:'计算期间参数或配置发生变化，结果属于原输入快照'}:{})});
 }catch(e){error.value=(e as Error).message;}finally{busy.value=false;emit('activity',false);}
}
defineExpose({isBusy:()=>busy.value});
</script>
<template>
 <section class="peak-calculations" aria-label="材料参数与自定义公式">
  <div class="peak-section-heading"><div><h3>材料参数与自定义公式</h3><p class="hint">仅使用已确认的峰参数；缺字段或不适用的样品分别报告，不以零填补。</p></div><button v-if="!methods.length" :disabled="loading" @click="load">{{loading?'加载计算方法…':'重新加载计算方法'}}</button></div>
  <fieldset :disabled="busy||loading" class="peak-calculation-fields"><legend>计算设置</legend><div class="peak-form-grid"><label>计算方法<select v-model="draft.method" @change="selectMethod"><option v-for="m in methods" :key="m.id" :value="m.id">{{m.title}}</option></select></label><label>计算范围<select v-model="scope" @change="selectionChanged"><option value="all">全部 {{props.records.length}} 条峰记录</option><option value="selected">手动选择峰记录</option></select></label></div>
   <p class="hint">{{method?.description}}</p><div v-if="scope==='selected'" class="peak-selection-list"><label v-for="r in props.records" :key="r.id"><input v-model="selected" type="checkbox" :value="r.id" @change="selectionChanged" />{{r.sample_id}} · {{r.peak_id}} · {{r.source.filename}}</label></div>
   <template v-if="draft.method==='formula'">
    <div class="peak-form-grid"><label>公式执行范围<select v-model="draft.config.scope" @change="edited"><option value="row">逐峰</option><option value="sample">按样品分组</option><option value="spectrum">按谱分组</option></select></label><label>公式适用条件<input v-model="draft.config.applicability" @input="edited" /></label></div><h4>变量绑定</h4><p class="hint">变量可引用当前峰字段或带单位的常量。输出可引用前一步输出；实际允许的运算和单位由计算引擎检查。</p>
    <div class="peak-table-scroll"><table><thead><tr><th>变量名</th><th>来源</th><th>字段／数值</th><th>单位</th><th>分组聚合</th><th>操作</th></tr></thead><tbody><tr v-for="(v,name) in draft.config.variables" :key="name"><td><input :value="name" :aria-label="`变量 ${name} 名称`" @change="renameVariable(String(name),($event.target as HTMLInputElement).value)" /></td><td><select :value="v.field?'field':v.metadata?'metadata':'constant'" :aria-label="`变量 ${name} 来源`" @change="bindingMode(String(name),($event.target as HTMLSelectElement).value)"><option value="field">峰参数</option><option value="constant">常量</option><option value="metadata">实验元数据</option></select></td><td><select v-if="v.field" v-model="v.field" :aria-label="`变量 ${name} 字段`" @change="edited"><option v-for="(label,key) in FIELD_LABELS" :key="key" :value="key">{{label}}</option></select><input v-else-if="v.metadata!==undefined" v-model="v.metadata" :aria-label="`变量 ${name} 元数据键`" @input="edited" /><input v-else v-model.number="v.value" type="number" step="any" :aria-label="`常量 ${name} 数值`" @input="edited" /></td><td><span v-if="v.field">沿用字段单位</span><input v-else v-model="v.unit" :aria-label="`常量 ${name} 单位`" @input="edited" /></td><td><select v-if="v.field||v.metadata!==undefined" v-model="v.aggregate" :aria-label="`变量 ${name} 聚合`" @change="if(!v.aggregate)delete v.aggregate;edited()"><option value="">不聚合／组内一致值</option><option value="sum">求和</option><option value="mean">平均值</option></select></td><td><button type="button" @click="delete draft.config.variables[name];edited()">移除</button></td></tr></tbody></table></div><button type="button" data-test="add-formula-variable" @click="addVariable">添加变量</button>
    <h4>输出表达式</h4><div v-for="(out,i) in draft.config.outputs" :key="i" class="peak-formula-output" data-formula-output><label>输出名<input v-model="out.name" @input="edited" /></label><label class="peak-expression">计算表达式<input v-model="out.expression" :data-test="`formula-expression-${i}`" spellcheck="false" placeholder="如 (area - offset) / slope" @input="edited" /></label><label>输出单位<input v-model="out.unit" @input="edited" /></label><button type="button" :disabled="draft.config.outputs.length<=1" @click="draft.config.outputs.splice(i,1);edited()">移除</button></div><button type="button" data-test="add-formula-output" @click="addOutput">添加下一步输出</button>
   </template>
   <div v-else class="peak-form-grid">
    <template v-for="f in method?.fields??[]" :key="f.key">
     <label v-if="f.type==='number'">{{f.label}}<input v-model.number="draft.config[f.key]" type="number" step="any" @input="edited" /><small>{{f.help}}</small></label>
     <label v-else-if="f.type==='text'">{{f.label}}<input v-model="draft.config[f.key]" @input="edited" /><small>{{f.help}}</small></label>
     <label v-else-if="f.type==='select'">{{f.label}}<select v-model="draft.config[f.key]" @change="edited"><option v-for="o in f.options??[]" :key="optionValue(o)" :value="optionValue(o)">{{optionLabel(o)}}</option></select><small>{{f.help}}</small></label>
     <label v-else-if="f.type==='boolean'" class="peak-checkbox"><input v-model="draft.config[f.key]" type="checkbox" @change="edited" />{{f.label}}<small>{{f.help}}</small></label>
     <fieldset v-else-if="['wavelength','d0','measured_d'].includes(f.key)" class="peak-quantity-field"><legend>{{f.label}}</legend><label v-if="f.key==='measured_d'" class="peak-checkbox"><input :checked="draft.config[f.key]!=null" type="checkbox" @change="optionalQuantity(f.key,($event.target as HTMLInputElement).checked)" />直接输入已知 d（否则由峰位计算）</label><div v-if="draft.config[f.key]" class="peak-form-grid"><label>数值<input v-model.number="draft.config[f.key].value" type="number" step="any" @input="edited" /></label><label>单位<select v-model="draft.config[f.key].unit" @change="edited"><option value="nm">nm</option><option value="angstrom">Å</option><option value="m">m</option></select></label></div><small>{{f.help}}</small></fieldset>
     <fieldset v-else-if="isHkl(f.key)" class="peak-hkl"><legend>{{f.label}}</legend><label v-if="f.key==='hkl'&&draft.method==='lattice'" class="peak-checkbox"><input :checked="draft.config[f.key]!=null" type="checkbox" @change="toggleHkl(f.key,($event.target as HTMLInputElement).checked)" />提供共同 hkl</label><template v-if="draft.config[f.key]"><label v-for="(n,i) in ['h','k','l']" :key="n">{{n}}<input v-model.number="draft.config[f.key][i]" type="number" step="1" @input="edited" /></label></template><p class="hint">{{f.help}}</p></fieldset>
     <fieldset v-else-if="f.key==='hkl_by_record'" class="peak-structured-field"><legend>{{f.label}}</legend><p class="hint">按峰覆盖共同 hkl；不勾选时使用共同值。不会自动识别物相。</p><div class="peak-table-scroll"><table><thead><tr><th>使用独立 hkl</th><th>样品／峰</th><th>h</th><th>k</th><th>l</th></tr></thead><tbody><tr v-for="r in records" :key="r.id"><td><input type="checkbox" :checked="Boolean(draft.config.hkl_by_record?.[r.id])" :aria-label="`${r.peak_id} 独立hkl`" @change="setRecordHkl(r.id,($event.target as HTMLInputElement).checked)" /></td><th>{{r.sample_id}} / {{r.peak_id}}</th><td v-for="(n,j) in ['h','k','l']" :key="n"><input v-if="draft.config.hkl_by_record?.[r.id]" v-model.number="draft.config.hkl_by_record[r.id][j]" type="number" step="1" :aria-label="`${r.peak_id} ${n}`" @input="edited" /><span v-else>沿用共同值</span></td></tr></tbody></table></div></fieldset>
     <fieldset v-else-if="f.key==='correction'" class="peak-structured-field"><legend>{{f.label}}</legend><div class="peak-form-grid"><label>校正方式<select v-model="draft.config.correction.mode" @change="correctionModeChanged"><option value="corrected">已校正的样品宽度</option><option v-if="draft.method!=='williamson_hall'" value="gaussian">Gaussian 标准样平方差</option><option value="lorentz">Lorentz 标准样宽度差</option><option v-if="draft.method!=='williamson_hall'" value="apparent">未校正表观值（明确标注）</option></select></label><label>校正来源或表观估计依据<input v-model="draft.config.correction.source" @input="edited" /></label><label class="peak-checkbox"><input v-model="draft.config.correction.conditions_match" type="checkbox" data-test="correction-conditions" @change="edited" />已核对测量条件、角度和宽度定义相容</label></div><template v-if="['gaussian','lorentz'].includes(draft.config.correction.mode)"><label>仪器宽度输入<select :value="draft.config.correction.instrument_table?'table':'single'" @change="correctionInput(($event.target as HTMLSelectElement).value)"><option value="single">同角度单个标准样宽度</option><option value="table">按角度插值的标准样表</option></select></label><div v-if="!draft.config.correction.instrument_table" class="peak-form-grid"><label>仪器 FWHM<input :value="draft.config.correction.instrument_width?.value??''" type="number" step="any" data-test="instrument-width-value" @input="draft.config.correction.instrument_width??={unit:'deg'};draft.config.correction.instrument_width.value=Number(($event.target as HTMLInputElement).value);edited()" /></label><label>宽度单位<select :value="draft.config.correction.instrument_width?.unit??'deg'" @change="draft.config.correction.instrument_width??={value:null};draft.config.correction.instrument_width.unit=($event.target as HTMLSelectElement).value;edited()"><option value="deg">deg</option><option value="rad">rad</option></select></label></div><template v-else><div class="peak-form-grid"><label>2θ 单位<select v-model="draft.config.correction.position_unit" @change="edited"><option value="deg">deg</option><option value="rad">rad</option></select></label><label>宽度单位<select v-model="draft.config.correction.width_unit" @change="edited"><option value="deg">deg</option><option value="rad">rad</option></select></label></div><div class="peak-table-scroll"><table><thead><tr><th>2θ</th><th>仪器 FWHM</th><th>操作</th></tr></thead><tbody><tr v-for="(r,i) in draft.config.correction.instrument_table" :key="i"><td><input v-model.number="r.position" type="number" step="any" :aria-label="`标准样第${Number(i)+1}行2θ`" @input="edited" /></td><td><input v-model.number="r.width" type="number" step="any" :aria-label="`标准样第${Number(i)+1}行宽度`" @input="edited" /></td><td><button type="button" @click="draft.config.correction.instrument_table.splice(i,1);edited()">移除</button></td></tr></tbody></table></div><button type="button" @click="addInstrumentRow">添加标准样点</button><details><summary>粘贴标准样 CSV</summary><p class="hint">每行两列：2θ、仪器 FWHM；以逗号或 Tab 分隔，可含一行表头。</p><textarea v-model="csvInput.correction" rows="4" aria-label="仪器标准样CSV" /><button type="button" @click="instrumentCsv">解析并替换标准样表</button></details></template></template><p class="hint">仪器表只在覆盖范围内插值；Pseudo-Voigt 等混合峰形需提供有来源的已校正宽度。</p></fieldset>
     <fieldset v-else-if="f.key==='coefficients'" class="peak-structured-field"><legend>{{f.label}}</legend><label class="peak-checkbox"><input :checked="draft.config.coefficients!=null" type="checkbox" @change="toggleCoefficients(($event.target as HTMLInputElement).checked)" />使用有来源的校准系数代替标样拟合</label><div v-if="draft.config.coefficients" class="peak-form-grid"><label v-for="(label,key) in {slope:'斜率',intercept:'截距',min_concentration:'有效浓度下限',max_concentration:'有效浓度上限'}" :key="key">{{label}}<input v-model.number="draft.config.coefficients[key]" type="number" step="any" @input="edited" /></label><label>校准来源<input v-model="draft.config.coefficients.source" @input="edited" /></label></div><small>{{f.help}}</small></fieldset>
     <fieldset v-else-if="f.key==='integration_range'" class="peak-structured-field"><legend>{{f.label}}</legend><label class="peak-checkbox"><input :checked="draft.config.integration_range!=null" type="checkbox" @change="draft.config.integration_range=($event.target as HTMLInputElement).checked?[0,1]:null;edited()" />提供与标样相同的积分范围</label><div v-if="draft.config.integration_range" class="peak-form-grid"><label>下限<input v-model.number="draft.config.integration_range[0]" type="number" step="any" @input="edited" /></label><label>上限<input v-model.number="draft.config.integration_range[1]" type="number" step="any" @input="edited" /></label></div><small>{{f.help}}</small></fieldset>
     <fieldset v-else-if="isTable(f)" class="peak-structured-field"><legend>{{f.label}}</legend><p class="hint">{{f.help}}</p><div class="peak-table-scroll"><table><thead><tr><th v-for="col in tableColumns(f)" :key="col">{{col}}</th><th>操作</th></tr></thead><tbody><tr v-for="(row,i) in draft.config[f.key]??[]" :key="i"><td v-for="col in tableColumns(f)" :key="col"><input v-model.number="row[col]" type="number" step="any" :aria-label="`${f.label} 第${Number(i)+1}行 ${col}`" @input="edited" /></td><td><button type="button" @click="draft.config[f.key].splice(i,1);edited()">移除</button></td></tr></tbody></table></div><button type="button" @click="addTableRow(f)">添加一行</button><details><summary>粘贴表格／CSV</summary><p class="hint">列顺序：{{tableColumns(f).join('，')}}。可含一行表头，用逗号或 Tab 分隔。</p><textarea v-model="csvInput[f.key]" :aria-label="`${f.label} CSV数据`" rows="4" /><button type="button" @click="parseCsv(f)">解析并替换此表</button></details></fieldset>
     <fieldset v-else class="peak-structured-field"><legend>{{f.label}}</legend><p class="hint">{{f.help}}</p><div v-for="[key,value] in objectEntries(f)" :key="key" class="peak-form-grid"><label>{{key}}<input :value="value" :type="typeof value==='number'?'number':'text'" step="any" @input="draft.config[f.key][key]=typeof value==='number'?Number(($event.target as HTMLInputElement).value):($event.target as HTMLInputElement).value;edited()" /></label><button type="button" @click="delete draft.config[f.key][key];edited()">移除</button></div><form @submit.prevent="addObjectField(f,$event)" class="peak-inline-actions"><label>字段名<input name="key" /></label><button type="submit">添加字段</button></form></fieldset>
    </template>
   </div>
  </fieldset>
  <p v-if="error" role="alert" class="error">{{error}}</p><p v-if="validation" role="status" class="hint">{{validation}}</p>
  <div class="peak-inline-actions"><button :disabled="busy||!records.length||!method" @click="run(true)">检查表达式与配置</button><button class="primary" :disabled="busy||!records.length||!method" data-test="calculate-material" @click="run(false)">{{busy?'正在计算…':`计算 ${records.length} 条峰记录`}}</button></div>
  <section v-if="history.length" class="peak-calculation-history"><h3>计算结果与历史</h3><details v-for="(h,i) in [...history].reverse()" :key="h.id" :open="i===0"><summary>{{methods.find(m=>m.id===h.request.method)?.title??h.request.method}} · {{new Date(h.created_at).toLocaleString()}} · {{h.stale?'已失效，保留历史':'已保存结果'}}</summary><p v-if="h.stale" class="warning">{{h.stale_reason}}。需重新计算后用于当前设置。</p><div class="peak-table-scroll"><table><thead><tr><th>样品 / 峰</th><th>结果</th><th>状态与说明</th></tr></thead><tbody><tr v-for="(r,j) in h.response.results" :key="j"><th>{{r.sample_id}}<small>{{r.record_ids.join(' / ')}}</small></th><td><div v-for="(v,name) in r.values" :key="name"><strong>{{name}}：{{v.value==null?'—':Number(v.value.toPrecision(9))}} {{v.unit}}</strong><small>{{v.definition}}</small></div><span v-if="!Object.keys(r.values).length">未产生有效值</span></td><td>{{r.status==='valid'?'有效计算':r.status==='apparent'?'表观估计':'无法计算'}}<p v-if="r.error">{{r.error.message}} [{{r.error.code}}]</p><p v-for="w in r.warnings" :key="w">{{w}}</p></td></tr></tbody></table></div><details><summary>方法、输入与完整回归明细</summary><pre>{{JSON.stringify({request:h.request,response:h.response},null,2)}}</pre></details></details></section>
 </section>
</template>
